function reviewPaneSelectionGuard({before,after,edit}) {
  function assert(value,message) { if (!value) throw new Error(message); }
  assert(typeof before==="string"&&typeof after==="string","source inputs required");
  assert(before.split(edit.before).length===2,"one unique preimage");
  assert(after===before.replace(edit.before,edit.after),"exact forward edit");
  assert(after.split(edit.after).length===2&&after.replace(edit.after,edit.before)===before,"complete inverse");
  const comparator="    if ($r.Width*$r.Height -gt $area) { $area = $r.Width*$r.Height; $largest = $item }\n";
  assert(edit.before.endsWith(comparator)&&edit.after.endsWith(comparator),"original comparator/order preserved");
  assert(edit.after.includes("$r.IsEmpty -or $item.Current.IsOffscreen -or $r.Width -le 0 -or $r.Height -le 0"),"empty/offscreen/nonpositive guard");
  assert(edit.after.includes("@($r.X, $r.Y, $r.Width, $r.Height, $r.Right, $r.Bottom, ($r.Width*$r.Height))"),"all fixed geometry fields");
  assert(edit.after.includes("[double]::IsNaN($paneCoordinate) -or [double]::IsInfinity($paneCoordinate)")&&edit.after.includes("if (-not $paneBoundsFinite) { continue }"),"nonfinite rejection");
  function rect(x,y,width,height,offscreen=false) {
    return {X:x,Y:y,Width:width,Height:height,Right:x+width,Bottom:y+height,IsEmpty:false,IsOffscreen:offscreen};
  }
  function accepted(r) {
    return !r.IsEmpty&&!r.IsOffscreen&&r.Width>0&&r.Height>0&&
      [r.X,r.Y,r.Width,r.Height,r.Right,r.Bottom,r.Width*r.Height].every(Number.isFinite);
  }
  function select(items,guard) {
    let largest=null,area=0;
    for (const item of items) {
      if (guard&&!accepted(item)) continue;
      const candidate=item.Width*item.Height;
      if (candidate>area) { area=candidate;largest=item; }
    }
    return largest;
  }
  const empty={X:Infinity,Y:Infinity,Width:-Infinity,Height:-Infinity,Right:-Infinity,Bottom:-Infinity,IsEmpty:true,IsOffscreen:false};
  const valid=rect(24,48,320,681),negativeOrigin=rect(-1920,-100,320,681),compact=rect(24,48,48,681);
  const cases=[
    ["Rect.Empty",empty,false],
    ["zero width",rect(0,0,0,20),false],
    ["zero height",rect(0,0,20,0),false],
    ["negative width",rect(0,0,-1,20),false],
    ["offscreen",rect(0,0,20,20,true),false],
    ["NaN X",rect(NaN,0,20,20),false],
    ["NaN Y",rect(0,NaN,20,20),false],
    ["NaN width",rect(0,0,NaN,20),false],
    ["NaN height",rect(0,0,20,NaN),false],
    ["infinite X",rect(Infinity,0,20,20),false],
    ["infinite width",rect(0,0,Infinity,20),false],
    ["right-edge overflow",rect(Number.MAX_VALUE,0,Number.MAX_VALUE,1),false],
    ["bottom-edge overflow",rect(0,Number.MAX_VALUE,1,Number.MAX_VALUE),false],
    ["finite-dimension area overflow",rect(0,0,1e200,1e200),false],
    ["finite open pane",valid,true],
    ["finite compact pane",compact,true],
    ["valid negative origin",negativeOrigin,true]
  ];
  for(const [name,r,wanted]of cases) assert(accepted(r)===wanted,name);
  assert(select([valid,empty],false)===empty,"documented old-selector counterexample");
  assert(select([valid,empty],true)===valid,"empty cannot replace valid candidate");
  assert(select([empty,valid],true)===valid,"valid candidate after empty");
  const tie=rect(50,50,320,681);
  assert(select([valid,tie],true)===valid,"first equal-area candidate retained");
  assert(select([compact,valid],true)===valid,"largest finite area retained");
  assert(select([empty,rect(0,0,0,20)],true)===null,"no usable pane remains failure");
  return {status:"passed",scope:"V8 source checks and independent IEEE-754 geometry model; no PowerShell parser, UIA, .NET or native execution",sourceChecks:8,geometryCases:cases.length,selectionCases:6,cases:cases.map(([name,,expected])=>({name,expectedAccepted:expected}))};
}
